mapper.select:
where o.status != 'DELETED'
and o.organization_code ilike concat('%', #{organizationCodeFilter}, '%')
order by o.organization_code asc limit #{size} offset #{offset}

select relation_id as "relationId", organization_code as "organizationCode", parent_organization_code as "parentOrganizationCode", effective_start_date as "effectiveStartDate", effective_end_date as "effectiveEndDate", status as "status", change_reason as "changeReason" from organization_relations where organization_code = #{organizationCode} and status = 'ACTIVE'
and relation_id != #{excludeRelationId}
and effective_start_date <= #{endDate}
and (effective_end_date is null or effective_end_date >= #{startDate}) order by effective_start_date desc limit 1
